<!doctype html><html lang="en"><head><meta charset="utf-8"><title>Waybill {{ $shipment->tracking_code }}</title><style>body{font:14px Arial,sans-serif;margin:28px;color:#17211c}.box{border:2px solid #1f6f5b;padding:22px;max-width:760px;margin:auto}.top{display:flex;justify-content:space-between;gap:24px;align-items:flex-start}h1{margin:0}.code{max-width:260px;text-align:center}.code img{width:150px;height:150px}.barcode svg{max-width:100%;height:60px}.tracking{font:700 18px monospace;letter-spacing:1px}dl{display:grid;grid-template-columns:160px 1fr;gap:8px}.muted{color:#52615a;font-size:12px}@media print{button{display:none}.box{border:0;margin:0;padding:0}}</style></head><body><button type="button" onclick="window.print()">Print waybill</button><main class="box"><div class="top"><section><h1>SUKI SHOP Waybill</h1><p class="tracking">{{ $shipment->tracking_code }}</p><p class="muted">Shipment status: {{ $shipment->workflow_status?->value }}</p></section><section class="code" aria-label="Tracking QR code" data-tracking-payload="{{ $shipment->tracking_code }}"><img src="{{ $qrDataUri }}" alt="QR code for tracking {{ $shipment->tracking_code }}"><div class="barcode" aria-label="Barcode for tracking {{ $shipment->tracking_code }}" data-tracking-payload="{{ $shipment->tracking_code }}">{!! $barcodeSvg !!}</div><p class="muted">Scan to identify this shipment</p></section></div><dl><dt>Seller / pickup</dt><dd>{{ $shipment->sellerOrder->seller->name }} — {{ $shipment->sellerOrder->order->street_address }}, {{ $shipment->sellerOrder->order->municipality }}</dd><dt>Buyer / delivery</dt><dd>{{ $shipment->sellerOrder->order->recipient_name }} — {{ $shipment->sellerOrder->order->street_address }}, {{ $shipment->sellerOrder->order->municipality }}, {{ $shipment->sellerOrder->order->province }}</dd><dt>COD amount</dt><dd>₱{{ number_format($shipment->cod_amount_minor / 100, 2) }}</dd><dt>Logistics</dt><dd>{{ $shipment->provider?->name ?? 'Pending assignment' }}</dd><dt>Riders</dt>